'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useRef, useState, type PointerEvent } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { hold } from '@/registry/ndeko/lib/demonstration';
import { ChevronsUpDownIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import {
  indexOfOption,
  InlineListbox,
  LISTBOX_PADDING_PX,
  OPTION_HEIGHT_PX,
  optionValueAt,
  type ListOption,
} from './_parts/inline-listbox';
import {
  useInlineListbox,
  type InlineListboxControl,
} from './_parts/use-inline-listbox';

const SLIDE_THRESHOLD_PX = 6;

const TRIGGER = [
  'bg-card hairline-ring ring-foreground/12 flex h-8 w-full cursor-pointer touch-none items-center justify-between gap-2 rounded-md px-2 text-[13px] shadow-[0_1px_2px_rgb(0_0_0/0.05)]',
  'dark:bg-foreground/[0.04] dark:ring-foreground/15 outline-none select-none',
  'focus-visible:ring-ring/25 focus-visible:ring-[3px]',
].join(' ');

type Press = {
  x: number;
  y: number;
  hasSlid: boolean;
};

function labelOfValue(options: readonly ListOption[], value: string) {
  const option = options.find((candidate) => candidate.value === value);
  if (option) {
    return option.label;
  }
  return '';
}

function listTopOf(index: number) {
  const rowsAbove = index * OPTION_HEIGHT_PX;
  return -(LISTBOX_PADDING_PX + rowsAbove);
}

function originYOf(index: number) {
  const rowsAbove = index * OPTION_HEIGHT_PX;
  const rowCenter = OPTION_HEIGHT_PX / 2;
  return LISTBOX_PADDING_PX + rowsAbove + rowCenter;
}

function enterScaleOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 1;
  }
  return 0.96;
}

export type SlideSelectProps = InlineListboxControl & {
  label: string;
  className?: string;
};

export function SlideSelect({
  label,
  className,
  ...control
}: SlideSelectProps) {
  const { options, value } = control;
  const listboxRef = useRef<HTMLDivElement>(null);
  const press = useRef<Press | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const {
    listId,
    rootRef,
    isOpen,
    activeValue,
    controlsId,
    activeId,
    openAround,
    close,
    pick,
    changeHighlight,
    handleKey,
  } = useInlineListbox(control);
  const currentIndex = indexOfOption(options, value);
  const currentLabel = labelOfValue(options, value);

  function startPress(event: PointerEvent<HTMLButtonElement>) {
    if (event.button !== 0) {
      return;
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    press.current = { x: event.clientX, y: event.clientY, hasSlid: false };
    openAround();
  }

  function slidePress(event: PointerEvent<HTMLButtonElement>) {
    const start = press.current;
    if (!start) {
      return;
    }
    const travel = Math.hypot(event.clientX - start.x, event.clientY - start.y);
    if (travel > SLIDE_THRESHOLD_PX) {
      start.hasSlid = true;
    }
    if (!start.hasSlid) {
      return;
    }
    const under = optionValueAt(
      listboxRef.current,
      event.clientX,
      event.clientY
    );
    changeHighlight(under);
  }

  function endPress(event: PointerEvent<HTMLButtonElement>) {
    const start = press.current;
    press.current = null;
    if (!start || !start.hasSlid) {
      return;
    }
    const under = optionValueAt(
      listboxRef.current,
      event.clientX,
      event.clientY
    );
    if (under === null) {
      close();
      return;
    }
    pick(under);
  }

  function cancelPress() {
    press.current = null;
    close();
  }

  const enter = { opacity: 0, scale: enterScaleOf(shouldReduceMotion) };
  const listStyle = {
    top: listTopOf(currentIndex),
    left: -LISTBOX_PADDING_PX,
    right: -LISTBOX_PADDING_PX,
    transformOrigin: `50% ${originYOf(currentIndex)}px`,
  };

  return (
    <div ref={rootRef} className={cn('relative', className)}>
      <button
        type='button'
        role='combobox'
        aria-label={label}
        aria-haspopup='listbox'
        aria-expanded={isOpen}
        aria-controls={controlsId}
        aria-activedescendant={activeId}
        onPointerDown={startPress}
        onPointerMove={slidePress}
        onPointerUp={endPress}
        onPointerCancel={cancelPress}
        onKeyDown={handleKey}
        className={TRIGGER}
      >
        <Swap swapKey={value} className='min-w-0'>
          <span className='truncate'>{currentLabel}</span>
        </Swap>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </button>
      <AnimatePresence>
        {isOpen && (
          <motion.div
            style={listStyle}
            initial={enter}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.15, ease: [0.23, 1, 0.32, 1] }}
            className='absolute z-30'
          >
            <InlineListbox
              id={listId}
              label={label}
              options={options}
              value={value}
              highlighted={activeValue}
              onHighlight={changeHighlight}
              onPick={pick}
              listboxRef={listboxRef}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

type SettingId = 'repeat' | 'alert' | 'calendar';

type Setting = {
  id: SettingId;
  label: string;
  options: ListOption[];
};

const SETTINGS: Setting[] = [
  {
    id: 'repeat',
    label: 'Repeat',
    options: [
      { value: 'never', label: 'Never' },
      { value: 'day', label: 'Every day' },
      { value: 'week', label: 'Every week' },
      { value: 'month', label: 'Every month' },
      { value: 'year', label: 'Every year' },
    ],
  },
  {
    id: 'alert',
    label: 'Alert',
    options: [
      { value: 'none', label: 'None' },
      { value: 'start', label: 'At time of event' },
      { value: '5', label: '5 minutes before' },
      { value: '15', label: '15 minutes before' },
      { value: '60', label: '1 hour before' },
    ],
  },
  {
    id: 'calendar',
    label: 'Calendar',
    options: [
      { value: 'work', label: 'Work' },
      { value: 'home', label: 'Home' },
      { value: 'family', label: 'Family' },
      { value: 'birthdays', label: 'Birthdays' },
    ],
  },
];

type Values = Record<SettingId, string>;

const NO_HIGHLIGHTS: Record<SettingId, string | null> = {
  repeat: null,
  alert: null,
  calendar: null,
};

const RESTING_VALUES: Values = {
  repeat: 'week',
  alert: '15',
  calendar: 'home',
};

export default function Select52() {
  const [values, setValues] = useState(RESTING_VALUES);
  const [openId, setOpenId] = useState<SettingId | null>(null);
  const [highlights, setHighlights] = useState(NO_HIGHLIGHTS);
  const [announcement, setAnnouncement] = useState('');

  function highlightFor(id: SettingId, value: string | null) {
    setHighlights((current) => ({ ...current, [id]: value }));
  }

  function openList(id: SettingId) {
    setOpenId(id);
    highlightFor(id, values[id]);
  }

  function pickFromDemo(id: SettingId, value: string) {
    setValues((current) => ({ ...current, [id]: value }));
    setOpenId(null);
    highlightFor(id, null);
  }

  function changeFromPerson(setting: Setting, value: string) {
    const option = setting.options.find(
      (candidate) => candidate.value === value
    );
    setValues((current) => ({ ...current, [setting.id]: value }));
    if (option) {
      setAnnouncement(`${setting.label}: ${option.label}`);
    }
  }

  function changeOpen(id: SettingId, isOpen: boolean) {
    if (isOpen) {
      setOpenId(id);
      return;
    }
    setOpenId((current) => {
      if (current === id) {
        return null;
      }
      return current;
    });
  }

  function startOver() {
    setValues(RESTING_VALUES);
    setOpenId(null);
    setHighlights(NO_HIGHLIGHTS);
  }

  const steps: AutoplayStep[] = [
    { after: 2400, run: () => openList('repeat') },
    { after: 900, run: () => highlightFor('repeat', 'month') },
    { after: 700, run: () => highlightFor('repeat', 'day') },
    { after: 900, run: () => pickFromDemo('repeat', 'day') },
    { after: 1800, run: () => openList('alert') },
    { after: 900, run: () => highlightFor('alert', '5') },
    { after: 700, run: () => highlightFor('alert', 'start') },
    { after: 900, run: () => pickFromDemo('alert', 'start') },
    { after: 1800, run: () => openList('calendar') },
    { after: 900, run: () => highlightFor('calendar', 'family') },
    { after: 900, run: () => pickFromDemo('calendar', 'family') },
    { after: 1600, run: hold },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 2400,
    onReset: startOver,
  });

  useKeptHeight(ref);

  return (
    <div ref={ref} className='min-h-[22rem] w-full max-w-sm pt-4 pb-14'>
      <section
        aria-label='New event'
        className='bg-foreground/[0.025] rounded-xl p-1'
      >
        <h3 className='px-3 py-2.5 text-sm font-medium'>New event</h3>
        {SETTINGS.map((setting) => (
          <div
            key={setting.id}
            className='flex h-12 items-center justify-between gap-3 px-3'
          >
            <span className='text-[13px]'>{setting.label}</span>
            <SlideSelect
              label={setting.label}
              options={setting.options}
              value={values[setting.id]}
              onValueChange={(value) => changeFromPerson(setting, value)}
              open={openId === setting.id}
              onOpenChange={(isOpen) => changeOpen(setting.id, isOpen)}
              highlighted={highlights[setting.id]}
              onHighlightedChange={(value) => highlightFor(setting.id, value)}
              className='w-44'
            />
          </div>
        ))}
      </section>
      <LiveRegion message={announcement} />
    </div>
  );
}

'use client';

import { useEffect, type RefObject } from 'react';

import { MENU_ITEM } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { SelectedMark } from '@/registry/ndeko/ui/selected-mark';

export type ListOption = {
  value: string;
  label: string;
};

/** A row is `h-8` and the list is `p-1`: a list that opens around its trigger lines the rows up with these. */
export const OPTION_HEIGHT_PX = 32;

export const LISTBOX_PADDING_PX = 4;

const MARK =
  'absolute right-1.5 transition-[scale,opacity] duration-150 ease-(--ease-out-strong)';

function markStateOf(isSelected: boolean) {
  if (isSelected) {
    return 'scale-100 opacity-100';
  }
  return 'scale-75 opacity-0 duration-100';
}

function highlightAttributeOf(isHighlighted: boolean) {
  if (isHighlighted) {
    return '';
  }
  return undefined;
}

export function optionIdOf(listId: string, value: string) {
  return `${listId}-${value}`;
}

export function indexOfOption(options: readonly ListOption[], value: string) {
  return options.findIndex((option) => option.value === value);
}

export function nextHighlightOf(
  options: readonly ListOption[],
  current: string | null,
  key: string
) {
  const lastIndex = options.length - 1;
  const currentIndex = options.findIndex((option) => option.value === current);
  if (key === 'ArrowDown') {
    return options[Math.min(lastIndex, currentIndex + 1)].value;
  }
  if (key === 'ArrowUp') {
    return options[Math.max(0, currentIndex - 1)].value;
  }
  if (key === 'Home') {
    return options[0].value;
  }
  if (key === 'End') {
    return options[lastIndex].value;
  }
  return null;
}

/** With the pointer captured by the trigger, the row under it has to be found by position. */
export function optionValueAt(
  listbox: HTMLElement | null,
  x: number,
  y: number
) {
  if (!listbox) {
    return null;
  }
  const hit = document.elementFromPoint(x, y);
  const option = hit?.closest<HTMLElement>('[data-option]');
  if (!option || !listbox.contains(option)) {
    return null;
  }
  return option.dataset.option ?? null;
}

export function useDismissOutside(
  rootRef: RefObject<HTMLElement | null>,
  isOpen: boolean,
  onDismiss: () => void
) {
  useEffect(() => {
    if (!isOpen) {
      return;
    }
    function dismissOnOutsidePress(event: PointerEvent) {
      const root = rootRef.current;
      const target = event.target;
      if (!root || !(target instanceof Node)) {
        return;
      }
      if (root.contains(target)) {
        return;
      }
      onDismiss();
    }
    document.addEventListener('pointerdown', dismissOnOutsidePress);
    return () =>
      document.removeEventListener('pointerdown', dismissOnOutsidePress);
  }, [rootRef, isOpen, onDismiss]);
}

type InlineListboxProps = {
  id: string;
  label: string;
  options: readonly ListOption[];
  value: string;
  highlighted: string | null;
  onHighlight: (value: string) => void;
  onPick: (value: string) => void;
  listboxRef?: React.Ref<HTMLDivElement>;
  className?: string;
};

export function InlineListbox({
  id,
  label,
  options,
  value,
  highlighted,
  onHighlight,
  onPick,
  listboxRef,
  className,
}: InlineListboxProps) {
  return (
    <div
      ref={listboxRef}
      id={id}
      role='listbox'
      aria-label={label}
      className={cn('surface-raised rounded-xl p-1 outline-none', className)}
    >
      {options.map((option) => {
        const isSelected = option.value === value;
        const isHighlighted = option.value === highlighted;

        return (
          <div
            key={option.value}
            id={optionIdOf(id, option.value)}
            role='option'
            aria-selected={isSelected}
            data-option={option.value}
            data-highlighted={highlightAttributeOf(isHighlighted)}
            onPointerMove={() => onHighlight(option.value)}
            onClick={() => onPick(option.value)}
            className={cn(MENU_ITEM, 'cursor-pointer pr-8')}
          >
            {option.label}
            <SelectedMark className={cn(MARK, markStateOf(isSelected))} />
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { useId, useRef, useState, type KeyboardEvent } from 'react';

import {
  nextHighlightOf,
  optionIdOf,
  useDismissOutside,
  type ListOption,
} from './inline-listbox';

export type InlineListboxControl = {
  options: readonly ListOption[];
  value: string;
  onValueChange: (value: string) => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  highlighted?: string | null;
  onHighlightedChange?: (value: string | null) => void;
};

function idWhenOpen(isOpen: boolean, id: string | null) {
  if (isOpen && id !== null) {
    return id;
  }
  return undefined;
}

function activeOptionIdOf(listId: string, activeValue: string | null) {
  if (activeValue === null) {
    return null;
  }
  return optionIdOf(listId, activeValue);
}

/**
 * The state and the keyboard of a list drawn inline: the focus stays on the trigger, which names
 * the highlighted row with `aria-activedescendant`. Open and highlight can be driven from outside.
 */
export function useInlineListbox({
  options,
  value,
  onValueChange,
  open,
  onOpenChange,
  highlighted,
  onHighlightedChange,
}: InlineListboxControl) {
  const listId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const [ownOpen, setOwnOpen] = useState(false);
  const [ownHighlighted, setOwnHighlighted] = useState<string | null>(null);
  const isOpen = open ?? ownOpen;
  const activeValue = highlighted ?? ownHighlighted;
  const activeOptionId = activeOptionIdOf(listId, activeValue);
  const controlsId = idWhenOpen(isOpen, listId);
  const activeId = idWhenOpen(isOpen, activeOptionId);

  function changeOpen(next: boolean) {
    setOwnOpen(next);
    onOpenChange?.(next);
  }

  function changeHighlight(next: string | null) {
    setOwnHighlighted(next);
    onHighlightedChange?.(next);
  }

  function close() {
    changeOpen(false);
    changeHighlight(null);
  }

  function openAround() {
    changeHighlight(value);
    changeOpen(true);
  }

  function pick(next: string) {
    onValueChange(next);
    close();
  }

  useDismissOutside(rootRef, isOpen, close);

  function handleKey(event: KeyboardEvent<HTMLElement>) {
    const isActivation = event.key === 'Enter' || event.key === ' ';
    const isArrow = event.key === 'ArrowDown' || event.key === 'ArrowUp';
    if (!isOpen) {
      const opensList = isActivation || isArrow;
      if (opensList) {
        event.preventDefault();
        openAround();
      }
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      close();
      return;
    }
    if (event.key === 'Tab') {
      close();
      return;
    }
    if (isActivation) {
      event.preventDefault();
      pick(activeValue ?? value);
      return;
    }
    const next = nextHighlightOf(options, activeValue ?? value, event.key);
    if (next === null) {
      return;
    }
    event.preventDefault();
    changeHighlight(next);
  }

  return {
    listId,
    rootRef,
    isOpen,
    activeValue,
    controlsId,
    activeId,
    openAround,
    close,
    pick,
    changeHighlight,
    handleKey,
  };
}
